namespace Signspace.Matching
{
    /// <summary>
    /// Which hands this build can play with, in one place, with the reason attached (P2.7).
    ///
    /// THE DECISION: right hand only, and the left hand is switched off rather than half-wired.
    ///
    /// The evidence, all of it in `phases/p2-core-loop/left-hand-decision.md` and regenerated by
    /// `python3 scripts/mirror_sim.py`:
    ///
    ///   - the mirror is exact for the DATA. Mirroring a pose across x = 0 - `(x, y, z, w)` becomes
    ///     `(x, -y, -z, w)` - puts every one of the 26 bones within 0.01 deg of the true mirror, and
    ///     the shipped metric is mirror-invariant to the bit: all 36 ordered pairs of the six shapes
    ///     score identically before and after mirroring, wrist turns included. So the matcher needs
    ///     no change at all for a second hand.
    ///   - the mirror is NOT yet known to be right for the RIG. A pose carries rotations and no
    ///     positions, so nothing in a pose file can say whether OpenXR's left-hand joints hand us
    ///     frames that are already mirrored. If they are, mirroring the input mirrors it twice and a
    ///     perfect left hand reads about 180 deg - which is the same silence the app shows today.
    ///   - a left hand that reaches the matcher without any mirroring scores 97-176 deg on a perfect
    ///     attempt (measured), i.e. the coldest state the app has.
    ///
    /// Two outcomes out of three are "a left-hander sees nothing", and the third needs hardware to
    /// distinguish. Half-support is worse than none, so: none, said out loud, with the enable path
    /// written down and gated behind this one constant.
    ///
    /// TO ENABLE (after POSE-FORMAT 4.3's device test):
    ///   1. set `LeftHandSupported = true`;
    ///   2. set `MirrorLeftInput = true` or `false` to match whatever the test said about the frames;
    ///   3. run the two-hand check in `left-hand-decision.md` section 6: both hands in frame, right
    ///      hand holds a shape to lock, left hand open at your side, and confirm the lock survives.
    /// Nothing else in the project has to change: the matcher is already mirror-invariant.
    /// </summary>
    public static class HandSupport
    {
        /// <summary>
        /// False until POSE-FORMAT 4.3's device test has run. This is the whole switch: the left leg
        /// of every decision below reads it, so there is no way to half-enable left-hand play.
        /// </summary>
        public const bool LeftHandSupported = false;

        /// <summary>
        /// True when a tracked left hand must be mirrored into the right-handed reference frame
        /// before matching. Only read when <see cref="LeftHandSupported"/> is true; the device test
        /// in POSE-FORMAT 4.3 is what decides its value, which is why it is not guessed here.
        /// </summary>
        public const bool MirrorLeftInput = true;

        /// <summary>The user-facing line. Lives in the honest mirror, not in a toast (§6 copy budget).</summary>
        public const string OneLineExplanation =
            "This build reads your right hand. Left-hand play is not in this version.";

        /// <summary>Dev-facing reason. Logged once at bind, and shown in the debug overlay.</summary>
        public const string Why =
            "the mirror is exact for the poses, but no file can say whether OpenXR's left-hand joint " +
            "frames are already mirrored - POSE-FORMAT 4.3 is the device test that answers it";

        /// <summary>Can this hand feed the matcher at all?</summary>
        public static bool FeedsMatcher(MetaHandSource.Hand hand)
        {
            if (hand == MetaHandSource.Hand.Right) return true;
            return LeftHandSupported;
        }

        /// <summary>Does this hand's input need mirroring into the right-handed reference frame?</summary>
        public static bool MirrorsInput(MetaHandSource.Hand hand)
        {
            return LeftHandSupported && MirrorLeftInput && hand == MetaHandSource.Hand.Left;
        }

        /// <summary>One line for the debug overlay: what the build does with each hand, and why.</summary>
        public static string Report()
        {
            if (LeftHandSupported)
                return "left: on" + (MirrorLeftInput ? " (input mirrored)" : " (input as reported)");
            return "left: off - right-handed build (" + Why + ")";
        }
    }
}
